class Solution {
public:
    vector<int> findPermutation(vector<int>& nums) {
        int n = nums.size();
        vector<vector<int>> memo(n, vector<int>(1 << n, -1));
        vector<vector<int>> best_pick(n, vector<int>(1 << n, -1));

        auto get_score = [&](auto& self, int last, int mask) -> int {
            if (mask == (1 << n) - 1) {
                return abs(last - nums[0]);
            }
            if (memo[last][mask] != -1) return memo[last][mask];

            int min_score = 1e9, best_i = -1;
            for (int i = 1; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    int score = abs(last - nums[i]) + self(self, i, mask | (1 << i));
                    if (score < min_score) {
                        min_score = score;
                        best_i = i;
                    }
                }
            }
            best_pick[last][mask] = best_i;
            return memo[last][mask] = min_score;
        };

        get_score(get_score, 0, 1);

        vector<int> res = {0};
        int last = 0, mask = 1;
        for (int step = 0; step < n - 1; ++step) {
            int nxt = best_pick[last][mask];
            res.push_back(nxt);
            mask |= (1 << nxt);
            last = nxt;
        }
        return res;
    }
};

class Solution {
    public int[] findPermutation(int[] nums) {
        int n = nums.length;
        int[][] memo = new int[n][1 << n];
        int[][] bestPick = new int[n][1 << n];
        for (int[] row : memo) Arrays.fill(row, -1);

        getScore(0, 1, nums, memo, bestPick);

        int[] res = new int[n];
        res[0] = 0;
        int last = 0, mask = 1;
        for (int i = 1; i < n; i++) {
            int nxt = bestPick[last][mask];
            res[i] = nxt;
            mask |= (1 << nxt);
            last = nxt;
        }
        return res;
    }

    private int getScore(int last, int mask, int[] nums, int[][] memo, int[][] bestPick) {
        int n = nums.length;
        if (mask == (1 << n) - 1) {
            return Math.abs(last - nums[0]);
        }
        if (memo[last][mask] != -1) return memo[last][mask];

        int minScore = Integer.MAX_VALUE, bestI = -1;
        for (int i = 1; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                int score = Math.abs(last - nums[i]) + getScore(i, mask | (1 << i), nums, memo, bestPick);
                if (score < minScore) {
                    minScore = score;
                    bestI = i;
                }
            }
        }
        bestPick[last][mask] = bestI;
        return memo[last][mask] = minScore;
    }
}

var findPermutation = function(nums) {
    const n = nums.length;
    const memo = Array.from({length: n}, () => new Int32Array(1 << n).fill(-1));
    const bestPick = Array.from({length: n}, () => new Int32Array(1 << n).fill(-1));

    function getScore(last, mask) {
        if (mask === (1 << n) - 1) {
            return Math.abs(last - nums[0]);
        }
        if (memo[last][mask] !== -1) return memo[last][mask];

        let minScore = 1e9, bestI = -1;
        for (let i = 1; i < n; i++) {
            if (!(mask & (1 << i))) {
                const score = Math.abs(last - nums[i]) + getScore(i, mask | (1 << i));
                if (score < minScore) {
                    minScore = score;
                    bestI = i;
                }
            }
        }
        bestPick[last][mask] = bestI;
        return memo[last][mask] = minScore;
    }

    getScore(0, 1);

    const res = [0];
    let last = 0, mask = 1;
    for (let step = 0; step < n - 1; step++) {
        const nxt = bestPick[last][mask];
        res.push(nxt);
        mask |= (1 << nxt);
        last = nxt;
    }
    return res;
};
